const { test, expect } = require('@playwright/test');
const { once } = require('node:events');
const { WebSocketServer } = require('ws');

// A compact protocol-compatible dedicated-room simulator for browser E2E.
// Authoritative snapshots are generated by Node, never by a browser Worker.
const DEDICATED_HOST = 'nocny-kurs-server';
class LocalRoomRelay {
  constructor() {
    this.rooms = new Map();
    this.clients = new Set();
    this.nextPeerId = 1;
    this.guestSnapshots = [];
    this.guestTraces = [];
    this.guestInputs = [];
    this.dropGuestSnapshots = false;
    this.dropProbeReplies = false;
  }
  send(peer, message) {
    if (message.type === 'data' && message.payload?.kind === 'snapshot') {
      if (this.dropGuestSnapshots) return;
      this.guestSnapshots.push(message.payload.state);
    }
    if (message.type === 'data' && message.payload?.kind === 'traces') {
      this.guestTraces.push(message.payload.traces);
    }
    if (peer.socket.readyState === 1) peer.socket.send(JSON.stringify(message));
  }
  broadcast(room, payload) {
    for (const peer of room.peers) this.send(peer, {type:'data',from:DEDICATED_HOST,payload});
  }
  snapshot(room) {
    const carX = 800 + (room.tick * 1.5) % 1450;
    return {
      running:true,teamScore:0,bonusScore:0,wantedLevel:0,tick:room.tick,
      statusKey:'enRoute',statusParams:{},trafficLightTime:room.tick/60,
      players:room.peers.map(peer => ({
        id:peer.playerId,source:'remote',sourceId:peer.playerId,
        name:peer.name||'',x:peer.x,y:peer.y,score:0,hits:0,
        color:['#d6f36a','#ff806a','#72d9d0'][((peer.playerId-1)%3)],
        maxHealth:3,health:3,alive:true,facing:0,bodyFacing:0,
        walk:0,fireHeld:false,invuln:0,wastedTimer:0,stun:0,
        moveTime:0,lastAppliedInputSeq:peer.lastInputSeq||0,
        carId:null,vape:true
      })),
      cars:[{id:99,type:'car',x:carX,y:1400,angle:0,speed:90,
        health:10,destroyed:false,color:'#4f7791',brakeLight:0,
        turnSignal:null,driverId:null,npcInside:true}],
      guards:[],carDrivers:[],parcels:[],cashPacks:[],medkits:[],
      bullets:[],explosions:[],muzzleFlashes:[]
    };
  }
  tick(room) {
    room.tick += 1;
    for (const peer of room.peers) {
      const input=peer.lastInput;
      if (input) {
        peer.x=Math.max(40,Math.min(2760,peer.x+(input.dx||0)*155/60));
        peer.y=Math.max(40,Math.min(2160,peer.y+(input.dy||0)*155/60));
      }
    }
    this.broadcast(room,{kind:'snapshot',state:this.snapshot(room)});
    if(room.tick%6===0) this.broadcast(room,{kind:'traces',traces:room.traces});
  }
  injectTraces() {
    for (const room of this.rooms.values()) {
      room.traces={skidMarks:[[1260,1260,500,0]],
        deathRemains:[[1330,1330,1000,'#d6f36a',12000]]};
      this.broadcast(room,{kind:'traces',traces:room.traces});
    }
  }
  attach(socket) {
    const peer={id:'peer-'+this.nextPeerId++,socket,kind:'guest',roomId:null,
      playerId:null,x:1118,y:1030,name:'',lastInput:null,lastInputSeq:0};
    this.clients.add(peer);
    socket.on('message',raw => {
      let message;try {message=JSON.parse(raw.toString('utf8'));}catch{return;}
      if (message.type==='join' && !peer.roomId) {
        if(message.role!=='dedicated'){this.send(peer,{type:'error',code:'dedicated_required'});return;}
        const id=message.game+':'+message.key;
        let room=this.rooms.get(id);
        if(!room){
          room={peers:[],nextPlayerId:1,tick:0,traces:{skidMarks:[],deathRemains:[]},timer:null};
          this.rooms.set(id,room);
          room.timer=setInterval(()=>this.tick(room),1000/60);
        }
        if(room.peers.length>=8){this.send(peer,{type:'error',code:'room_full'});return;}
        peer.roomId=id;peer.playerId=room.nextPlayerId++;
        peer.x+=peer.playerId*25;peer.y+=peer.playerId*12;
        room.peers.push(peer);
        this.send(peer,{type:'joined',peerId:peer.id,hostPeerId:DEDICATED_HOST,peers:[]});
        this.send(peer,{type:'data',from:DEDICATED_HOST,
          payload:{kind:'welcome',to:peer.id,hostId:DEDICATED_HOST,playerId:peer.playerId}});
        this.send(peer,{type:'data',from:DEDICATED_HOST,
          payload:{kind:'snapshot',state:this.snapshot(room)}});
        this.send(peer,{type:'data',from:DEDICATED_HOST,
          payload:{kind:'traces',traces:room.traces}});
      } else if(message.type==='probe' && peer.roomId){
        if(!this.dropProbeReplies)this.send(peer,{type:'probe_ack',nonce:message.nonce});
      } else if(message.type==='data' && peer.roomId){
        const payload=message.payload||{};
        if(payload.kind==='input'){
          this.guestInputs.push(payload);
          peer.lastInput=payload;
          peer.lastInputSeq=payload.seq||0;
          if(typeof payload.name==='string')peer.name=payload.name;
        } else if(payload.kind==='ping'){
          this.send(peer,{type:'data',from:DEDICATED_HOST,
            payload:{kind:'pong',to:peer.id,sentAt:payload.sentAt}});
        }
      }
    });
    socket.on('close',()=>{
      if(peer.roomId){
        const room=this.rooms.get(peer.roomId);
        if(room){
          room.peers=room.peers.filter(p=>p!==peer);
          if(!room.peers.length){clearInterval(room.timer);this.rooms.delete(peer.roomId);}
        }
      }
      this.clients.delete(peer);
    });
  }
}

test('an NPC ambulance uses road traffic and can be taken over like a car',async({page})=>{
  await page.route('**/nocny-kurs/game.js*',async route=>{
    const response=await route.fetch(),source=await response.text();
    const anchor='  function gameSnapshot(){';
    expect(source).toContain(anchor);
    const hook=`window.__testAmbulance={
      dispatch(){cars=[];guards=[];addDeathRemain(players[0],762,1416);return hospital.exitY},
      pose(){return gameSnapshot().cars.find(c=>c.type==='ambulance')},
      steal(){
        const vehicle=cars.find(c=>c.type==='ambulance');
        const boarded=boardCar(players[0],vehicle);
        return {boarded,driver:vehicle.driver?.id,npcInside:vehicle.npcInside,
          displaced:carDrivers.some(d=>d.carId===vehicle.id)};
      }
    };\n`;
    await route.fulfill({response,body:source.replace(anchor,hook+anchor)});
  });
  await page.goto('/grand-t/');
  await page.locator('#start').click();
  const exitY=await page.evaluate(()=>window.__testAmbulance.dispatch());
  await expect.poll(()=>page.evaluate(()=>window.__testAmbulance.pose()?.y??0)).toBeGreaterThan(exitY+25);
  expect(await page.evaluate(()=>window.__testAmbulance.pose())).toMatchObject({health:10,npcInside:true,driverId:null});
  expect(await page.evaluate(()=>window.__testAmbulance.steal())).toEqual({boarded:true,driver:1,npcInside:false,displaced:true});
});

test('two browsers share a server-owned online room and keep syncing when creator stops rendering', async ({browser}) => {
  const relay=new LocalRoomRelay(),server=new WebSocketServer({host:'127.0.0.1',port:0});
  await once(server,'listening');server.on('connection',socket=>relay.attach(socket));
  const socketUrl='ws://127.0.0.1:'+server.address().port;
  const firstContext=await browser.newContext(),secondContext=await browser.newContext();
  try{
    for(const context of [firstContext,secondContext]){
      await context.route('**/nocny-kurs/multiplayer.js*',async route=>{
        const response=await route.fetch(),source=await response.text();
        const original="const SERVER = 'wss://gra.w.korzec-it.pl/ws';";
        expect(source).toContain(original);
        await route.fulfill({response,body:source.replace(original,"const SERVER = '"+socketUrl+"';")});
      });
      await context.route('**/nocny-kurs/game.js*',async route=>{
        const response=await route.fetch(),source=await response.text();
        const anchor='  function gameSnapshot(){';
        expect(source).toContain(anchor);
        const hooks=[
          'window.__testTraceState=()=>({',
          'marks:skidMarks.map(m=>({x:m.x,y:m.y})),',
          'remains:deathRemains.map(r=>({x:r.x,y:r.y,age:r.age}))',
          '});'
        ].join('\n');
        await route.fulfill({response,body:source.replace(anchor,hooks+'\n'+anchor)});
      });
    }
    const first=await firstContext.newPage();
    await first.goto('/grand-t/');
    await first.locator('#player-name-start').fill('Założyciel');
    await first.locator('#multiplayer-online').click();
    await expect(first.locator('#multiplayer-status')).toContainText('grasz jako P1');
    await expect(first.locator('#overlay')).toHaveClass(/hidden/);
    const key=await first.locator('#multiplayer-room-key').inputValue();
    expect(key).toMatch(/^[A-Z]{6}$/);
    await expect(first.locator('#multiplayer-room button')).toHaveCount(1);
    await expect(first.locator('#gt-room-code')).toHaveText(key);
    await expect(first.locator('#multiplayer-leave')).toBeVisible();
    await first.evaluate(()=>{
      window.__testCopiedInvite='';
      Object.defineProperty(navigator,'clipboard',{configurable:true,
        value:{writeText:async v=>{window.__testCopiedInvite=v;}}});
    });
    await first.locator('#multiplayer-copy').click();
    await expect.poll(()=>first.evaluate(()=>window.__testCopiedInvite))
      .toMatch(new RegExp('#room='+key+'$'));

    const second=await secondContext.newPage();
    await second.goto('/nocny-kurs/#room='+key);
    await expect(second.locator('#multiplayer-status')).toContainText('grasz jako P2');
    await expect(second.locator('#overlay')).toHaveClass(/hidden/);
    await expect.poll(()=>relay.guestSnapshots.some(s=>s.players.length===2)).toBe(true);
    await expect(second.locator('#player-list')).toContainText('Założyciel');
    await second.locator('#player-name-live').fill('Ala');
    await expect(first.locator('#player-list')).toContainText('Ala');
    await second.locator('#player-name-live').fill('');
    await expect(first.locator('#player-list')).toContainText('P2');

    relay.injectTraces();
    await expect.poll(()=>second.evaluate(()=>{
      const trace=window.__testTraceState();
      return trace.marks.some(m=>m.x===1260&&m.y===1260)&&
        trace.remains.some(r=>r.x===1330&&r.age>=10);
    })).toBe(true);
    const previous=relay.guestSnapshots.length;
    await first.evaluate(()=>{window.requestAnimationFrame=()=>0;});
    await second.bringToFront();
    await expect.poll(()=>relay.guestSnapshots.length).toBeGreaterThan(previous+5);
    const before=relay.guestSnapshots.at(-1).players.find(p=>p.id===2).x;
    // Input editing keeps keyboard focus; release it before testing movement controls.
    await second.locator('#player-name-live').evaluate(input=>input.blur());
    await second.keyboard.down('d');
    await expect.poll(()=>relay.guestInputs.some(x=>x.dx>0)).toBe(true);
    await expect.poll(()=>relay.guestSnapshots.at(-1).players.find(p=>p.id===2).x)
      .toBeGreaterThan(before+5);
    await second.keyboard.up('d');
    expect([...relay.clients].every(p=>p.kind==='guest')).toBe(true);
  }finally{
    await secondContext.close();await firstContext.close();
    await new Promise((resolve,reject)=>server.close(error=>error?reject(error):resolve()));
  }
});

test('creator may disconnect while other dedicated players continue playing',async({browser})=>{
  const relay=new LocalRoomRelay(),server=new WebSocketServer({host:'127.0.0.1',port:0});
  await once(server,'listening');server.on('connection',socket=>relay.attach(socket));
  const url='ws://127.0.0.1:'+server.address().port;
  const firstContext=await browser.newContext(),secondContext=await browser.newContext();
  try{
    for(const context of [firstContext,secondContext]){
      await context.route('**/nocny-kurs/multiplayer.js*',async route=>{
        const response=await route.fetch(),source=await response.text();
        await route.fulfill({response,body:source.replace(
          "const SERVER = 'wss://gra.w.korzec-it.pl/ws';","const SERVER = '"+url+"';")});
      });
    }
    const first=await firstContext.newPage();await first.goto('/grand-t/');
    await first.locator('#multiplayer-online').click();
    await expect(first.locator('#multiplayer-status')).toContainText('grasz jako P1');
    const code=await first.locator('#multiplayer-room-key').inputValue();
    const second=await secondContext.newPage();await second.goto('/nocny-kurs/#room='+code);
    await expect(second.locator('#multiplayer-status')).toContainText('grasz jako P2');
    await expect(second.locator('.player-entry')).toHaveCount(2);
    await first.locator('#multiplayer-leave').click();
    await expect(second.locator('.player-entry')).toHaveCount(1);
    const snapshotCount=relay.guestSnapshots.length;
    await expect.poll(()=>relay.guestSnapshots.length).toBeGreaterThan(snapshotCount+4);
    await expect(second.locator('#overlay')).toHaveClass(/hidden/);
    await expect(second.locator('#multiplayer-room-key')).toHaveValue(code);
    expect([...relay.clients].every(p=>p.kind==='guest')).toBe(true);
  }finally{
    await secondContext.close();await firstContext.close();
    await new Promise((resolve,reject)=>server.close(error=>error?reject(error):resolve()));
  }
});

test('settings are available before and during local play on a narrow screen', async ({ browser }) => {
  const context = await browser.newContext({ viewport: { width: 360, height: 740 }, isMobile: true, hasTouch: true, locale: 'pl-PL' });
  try {
    const page = await context.newPage();
    await page.goto('/grand-t/');
    await expect(page.locator('#multiplayer-room')).toBeHidden();
    await expect(page.locator('#gt-settings-open')).toBeVisible();
    await page.locator('#gt-settings-open').click();
    await expect(page.locator('#gt-settings-dialog')).toBeVisible();
    await page.locator('#gt-settings-name').fill('Tester');
    await page.locator('#language-select').selectOption('sv');
    await page.locator('#gt-settings-close').click();
    await expect(page.locator('#player-name-start')).toHaveValue('Tester');
    await expect(page.locator('#start')).toHaveText('Lokalt spel');
    await page.locator('#start').click();
    await page.locator('#gt-settings-open').click();
    await expect(page.locator('#gt-settings-name')).toHaveValue('Tester');
    await page.locator('#language-select').selectOption('pl');
    await page.locator('#gt-settings-close').click();
    await expect(page.locator('#start')).toHaveText('Gra lokalna');
    await page.locator('#multiplayer-leave').click();
    await expect(page.locator('#overlay')).not.toHaveClass(/hidden/);
    await expect(page.locator('#player-name-start')).toHaveValue('Tester');
  } finally {
    await context.close();
  }
});

test('mobile online toolbar keeps all icons in one row without covering the logo', async ({ browser }) => {
  const relay = new LocalRoomRelay();
  const wsServer = new WebSocketServer({ host: '127.0.0.1', port: 0 });
  await once(wsServer, 'listening');
  wsServer.on('connection', socket => relay.attach(socket));
  const socketUrl = 'ws://127.0.0.1:' + wsServer.address().port;
  const context = await browser.newContext({
    viewport: { width: 320, height: 700 }, isMobile: true, hasTouch: true, locale: 'sv-SE'
  });
  try {
    await context.route('**/nocny-kurs/multiplayer.js*', async route => {
      const response = await route.fetch();
      const source = await response.text();
      const original = "const SERVER = 'wss://gra.w.korzec-it.pl/ws';";
      expect(source).toContain(original);
      await route.fulfill({ response, body: source.replace(original, "const SERVER = '" + socketUrl + "';") });
    });
    const page = await context.newPage();
    await page.goto('/grand-t/');
    await expect(page.locator('#gt-settings-open')).toBeVisible();

    await page.locator('#multiplayer-online').click();
    await expect(page.locator('#overlay')).toHaveClass(/hidden/);
    await expect(page.locator('#multiplayer-status')).toContainText('du spelar som P1');
    await expect(page.locator('.gt-topbar #multiplayer-copy')).toBeVisible();
    await expect(page.locator('.gt-topbar #multiplayer-leave')).toBeVisible();
    await expect(page.locator('.gt-topbar #gt-settings-open')).toBeVisible();
    await expect(page.locator('#gt-room-code')).toHaveText(await page.locator('#multiplayer-room-key').inputValue());
    await expect(page.locator('#language-select')).toHaveCount(1);

    const coords = await page.evaluate(() => {
      const bounds = selector => document.querySelector(selector).getBoundingClientRect();
      const logo = bounds('.topbar .brand-mark');
      const toolbar = bounds('.night-topbar-actions');
      const copy = bounds('#multiplayer-copy');
      const leave = bounds('#multiplayer-leave');
      const flag = bounds('#gt-settings-open');
      const brand = document.querySelector('.topbar .brand');
      const logoTarget = document.elementFromPoint(logo.left + logo.width / 2, logo.top + logo.height / 2);
      return {
        toolbarTop: toolbar.top, copyTop: copy.top, leaveTop: leave.top, flagTop: flag.top,
        logoRight: logo.right, controlsLeft: toolbar.left, brandRight: brand.getBoundingClientRect().right,
        logoClickable: brand.contains(logoTarget),
        roomRight: bounds('#multiplayer-room').right, flagRight: flag.right,
        copyRight: copy.right, leaveLeft: leave.left, leaveRight: leave.right, flagLeft: flag.left
      };
    });
    expect(Math.abs(coords.copyTop - coords.leaveTop)).toBeLessThan(2);
    expect(Math.abs(coords.leaveTop - coords.flagTop)).toBeLessThan(2);
    expect(coords.logoClickable).toBe(true);
    expect(coords.controlsLeft).toBeGreaterThanOrEqual(coords.logoRight);
    expect(coords.controlsLeft).toBeGreaterThanOrEqual(coords.brandRight - 1);
    expect(coords.copyRight).toBeLessThanOrEqual(coords.leaveLeft);
    expect(coords.leaveRight).toBeLessThanOrEqual(coords.flagLeft);
    expect(coords.flagRight).toBeLessThanOrEqual(320);

    await page.locator('#gt-settings-open').click();
    await page.locator('#language-select').selectOption('pl');
    await page.locator('#gt-settings-close').click();
    await expect(page.locator('#multiplayer-copy')).toHaveAttribute('aria-label','Kopiuj link');
    await page.locator('#multiplayer-leave').click();
    await expect(page.locator('#overlay')).not.toHaveClass(/hidden/);
    await expect(page.locator('#gt-settings-open')).toBeVisible();
  } finally {
    await context.close();
    await new Promise((resolve, reject) => wsServer.close(error => error ? reject(error) : resolve()));
  }
});

test('a Swedish guest sees local game status from a Polish host', async ({ browser }) => {
  const relay = new LocalRoomRelay();
  const wsServer = new WebSocketServer({ host: '127.0.0.1', port: 0 });
  await once(wsServer, 'listening');
  wsServer.on('connection', socket => relay.attach(socket));
  const socketUrl = 'ws://127.0.0.1:' + wsServer.address().port;
  const hostContext = await browser.newContext({ locale: 'pl-PL' });
  const guestContext = await browser.newContext({ locale: 'sv-SE' });
  try {
    for (const context of [hostContext, guestContext]) {
      await context.route('**/nocny-kurs/multiplayer.js*', async route => {
        const response = await route.fetch();
        const source = await response.text();
        const original = "const SERVER = 'wss://gra.w.korzec-it.pl/ws';";
        expect(source).toContain(original);
        await route.fulfill({ response, body: source.replace(original, "const SERVER = '" + socketUrl + "';") });
      });
    }

    const host = await hostContext.newPage();
    await host.goto('/grand-t/');
    await host.locator('#multiplayer-online').click();
    await expect(host.locator('#multiplayer-status')).toContainText('grasz jako P1');
    const code = await host.locator('#multiplayer-room-key').inputValue();

    const guest = await guestContext.newPage();
    await guest.goto('/nocny-kurs/#room=' + code);
    await expect(guest.locator('#multiplayer-status')).toContainText('du spelar som P2');
    await expect(guest.locator('#overlay')).toHaveClass(/hidden/);
    await expect.poll(() => relay.guestSnapshots.some(state => state.running && state.statusKey === 'enRoute')).toBe(true);
    await expect(guest.locator('#status')).toHaveText('TÄVLING PÅGÅR');
    await expect(host.locator('#status')).toHaveText('RYWALIZACJA');
    await guest.locator('#gt-settings-open').click();
    await guest.locator('#language-select').selectOption('pl');
    await guest.locator('#gt-settings-close').click();
    await expect(guest.locator('#status')).toHaveText('RYWALIZACJA');
  } finally {
    await guestContext.close();
    await hostContext.close();
    await new Promise((resolve, reject) => wsServer.close(error => error ? reject(error) : resolve()));
  }
});


test('guards shoot only players whose gunfire they personally witnessed in the last five seconds', async ({ page }) => {
  await page.route('**/nocny-kurs/game.js*', async route => {
    const response = await route.fetch();
    const source = await response.text();
    const anchor = '  function gameSnapshot(){';
    expect(source).toContain(anchor);
    const hooks = `
      window.__testGuardCombat = {
        spawned: () => guards.length,
        setup: ({ covered = false, ally = false, range = 200 } = {}) => {
          buildings = []; cars = []; carRespawns = []; bullets = [];
          const p = players[0];
          p.car = null; p.x = 1000 + range; p.y = 1000;
          p.alive = true; p.health = 3; p.invuln = 100;
          p.facing = 0; p.bodyFacing = 0; p.recentGunfire = 0;
          p.shotThisTick = false; p.fireHeld = false; p.fireCooldown = 0; p.stun = 0;
          p.pistolAmmo = 20; p.bazookaAmmo = 0;
          guards = [{ id: 900, x: 1000, y: 1000, color: '#f18161', facing: 0,
            walk: 0, stun: 0, hp: 2, fireCooldown: 0 }];
          if (ally) guards.push({ id: 901, x: 1100, y: 1000, color: '#e8a14e',
            facing: 0, walk: 0, stun: 0, hp: 2, fireCooldown: 999 });
          if (covered) buildings.push({ x: 1098, y: 970, w: 36, h: 60 });
        },
        firePlayer: () => {
          const p = players[0]; p.fireHeld = true; p.fireCooldown = 0;
          shoot(p); p.fireHeld = false;
        },
        uncover: () => { buildings = []; },
        setPlayerX: x => { players[0].x = x; },
        resetGuardShots: () => {
          bullets = [];
          for (const g of guards) g.fireCooldown = 0;
        },
        memory: () => guards[0].witnessedShots?.get(players[0].id) || 0,
        advance: frames => {
          for (let i = 0; i < frames; i++) update(1 / 60);
          return {
            guardShots: bullets.filter(b => b.team === 'guard').length,
            x: guards[0].x, walk: guards[0].walk,
            allyHp: guards[1]?.hp,
            recent: players[0].recentGunfire,
            memory: guards[0].witnessedShots?.get(players[0].id) || 0
          };
        }
      };
    `;
    await route.fulfill({ response, body: source.replace(anchor, hooks + anchor) });
  });

  await page.goto('/grand-t/');
  await page.locator('#start').click();
  const result = await page.evaluate(() => {
    const combat = window.__testGuardCombat;
    const spawned = combat.spawned();

    // A guard sees a peaceful player, but must not fire.
    combat.setup({ ally: true });
    const peaceful = combat.advance(17);
    combat.firePlayer();
    const witnessed = combat.advance(1);
    const allyHp = witnessed.allyHp;

    // Firing remains permitted while the witness memory is active, even
    // after the 3-second hearing/investigation memory has expired.
    combat.advance(60 * 4);
    combat.resetGuardShots();
    const fourSeconds = combat.advance(1);

    combat.advance(65);
    combat.resetGuardShots();
    const expired = combat.advance(1);

    // A shot heard behind a building must not authorize later firing,
    // even after the guard gets line of sight to the same player.
    combat.setup({ covered: true });
    combat.firePlayer();
    const hidden = combat.advance(1);
    combat.uncover();
    combat.resetGuardShots();
    const seenLater = combat.advance(1);

    // Out-of-range gunfire is also not witnessed retroactively.
    combat.setup({ range: 480 });
    combat.firePlayer();
    const farShot = combat.advance(1);
    combat.setPlayerX(1200);
    combat.resetGuardShots();
    const approachedLater = combat.advance(1);

    return { spawned, peaceful, witnessed, allyHp, fourSeconds, expired,
      hidden, seenLater, farShot, approachedLater };
  });

  expect(result.spawned).toBe(12);
  expect(result.peaceful.guardShots).toBe(0);
  expect(result.peaceful.x).toBeGreaterThan(1000);
  expect(result.witnessed.guardShots).toBeGreaterThan(0);
  expect(result.witnessed.memory).toBeGreaterThan(4.9);
  expect(result.allyHp).toBe(2);
  expect(result.fourSeconds.memory).toBeGreaterThan(0);
  expect(result.fourSeconds.recent).toBe(0);
  expect(result.fourSeconds.guardShots).toBeGreaterThan(0);
  expect(result.expired.memory).toBe(0);
  expect(result.expired.guardShots).toBe(0);
  expect(result.hidden.guardShots).toBe(0);
  expect(result.hidden.memory).toBe(0);
  expect(result.seenLater.guardShots).toBe(0);
  expect(result.seenLater.memory).toBe(0);
  expect(result.farShot.guardShots).toBe(0);
  expect(result.approachedLater.guardShots).toBe(0);
  expect(result.approachedLater.memory).toBe(0);
});

