        const impactingCar={id:-77,type:'car',x:secondOwner.x,y:secondOwner.y,angle:0,speed:150};
        hitPedestrians(impactingCar);
        const normalImpactHp=secondOwner.hp;
        const truck=cars.find(c=>!c.traffic&&c.type===TRUCK_TYPE);
        hijackCar(truck);
